using System;
using System.Diagnostics;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Net;
using System.Net.Sockets;
using System.Reflection;
using System.Xml.Linq;
using ModbusEmulatorX;

public static class TimelineTests {
 static void Check(bool value){if(!value)throw new Exception("Assertion failed.");}
 static void Near(double value,double expected){if(Math.Abs(value-expected)>0.00001)throw new Exception(value+" != "+expected);}
 static void Reject(Action action){bool rejected=false;try{action();}catch{rejected=true;}Check(rejected);}
 static TimelineStep Step(double at,TimelineAction action,double value=0,double duration=0){return new TimelineStep{AtSeconds=at,Action=action,Device="Process simulator",Point="Temperature",Value=value,DurationSeconds=duration};}
 static Timeline Plan(params TimelineStep[] steps){return new Timeline{Name="Test timeline",DurationSeconds=10,Steps=steps.ToList()};}
 public static void Run(Action<string,Action> test,string scratch){
  test("Timeline: immediate set and completion restore values and signal modes",()=>{var p=Project.Demo();var r=new TimelineRunner(p,Plan(Step(0,TimelineAction.SetValue,80)));r.Advance(0);Near(p.Devices[0].Points[0].Value,80);Check(p.Devices[0].Points[0].Simulation==Wave.Manual);r.Advance(10);Near(p.Devices[0].Points[0].Value,22.5);Check(r.Completed&&p.Devices[0].Points[0].Simulation==Wave.Sine);});
  test("Timeline: linear ramp and retained final state",()=>{var p=Project.Demo();var t=Plan(Step(0,TimelineAction.RampValue,42.5,10));t.RestoreOnFinish=false;var r=new TimelineRunner(p,t);r.Advance(5);Near(p.Devices[0].Points[0].Value,32.5);r.Advance(5);Near(p.Devices[0].Points[0].Value,42.5);Check(r.Completed);});
  test("Timeline: skipped ticks honor ordered ramp boundaries",()=>{var p=Project.Demo();var t=Plan(Step(0,TimelineAction.RampValue,50,2),Step(2,TimelineAction.RampValue,100,2),Step(5,TimelineAction.SetValue,75));var r=new TimelineRunner(p,t);r.Advance(3);Near(p.Devices[0].Points[0].Value,75);r.Advance(3);Near(p.Devices[0].Points[0].Value,75);});
  test("Timeline: timed faults restore prior settings at exact boundaries",()=>{var p=Project.Demo();p.Devices[0].DelayMs=12;var r=new TimelineRunner(p,Plan(Step(1,TimelineAction.SetDelay,250,2),Step(3,TimelineAction.SetDelay,100,1)));r.Advance(1);Check(p.Devices[0].DelayMs==250);r.Advance(2);Check(p.Devices[0].DelayMs==100);r.Advance(1);Check(p.Devices[0].DelayMs==12);});
  test("Timeline: independent simultaneous faults and values",()=>{var p=Project.Demo();var r=new TimelineRunner(p,Plan(Step(0,TimelineAction.SetDelay,200),Step(0,TimelineAction.SetDrop,25),Step(0,TimelineAction.SetException,4),Step(0,TimelineAction.SetResponse,0),Step(0,TimelineAction.SetValue,90),Step(2,TimelineAction.RestoreDevice)));r.Advance(0);var d=p.Devices[0];Check(!d.Responding&&d.DelayMs==200&&d.DropPercent==25&&d.ExceptionCode==4);Near(d.Points[0].Value,90);r.Advance(2);Check(d.Responding&&d.DelayMs==0&&d.DropPercent==0&&d.ExceptionCode==0);});
  test("Timeline: pause freezes time and resume continues",()=>{var p=Project.Demo();var r=new TimelineRunner(p,Plan(Step(0,TimelineAction.RampValue,42.5,10)));r.Advance(2);r.Pause();r.Advance(20);Near(r.Elapsed,2);Near(p.Devices[0].Points[0].Value,26.5);r.Resume();r.Advance(3);Near(r.Elapsed,5);Near(p.Devices[0].Points[0].Value,32.5);});
  test("Timeline: stop restores while paused and cannot resume",()=>{var p=Project.Demo();var r=new TimelineRunner(p,Plan(Step(0,TimelineAction.SetResponse,0)));r.Advance(0);r.Pause();r.Stop();r.Resume();r.Advance(1);Check(r.Completed&&p.Devices[0].Responding);Near(r.Elapsed,0);});
  test("Timeline: repeats restore baseline and support delayed updates",()=>{var p=Project.Demo();var t=Plan(Step(1,TimelineAction.SetValue,100));t.RepeatCount=3;var r=new TimelineRunner(p,t);r.Advance(10);Near(p.Devices[0].Points[0].Value,22.5);Check(r.Cycle==2);r.Advance(15);Near(p.Devices[0].Points[0].Value,100);Check(r.Cycle==3);r.Advance(5);Check(r.Completed);Near(p.Devices[0].Points[0].Value,22.5);Check(r.Evidence.Length==7);});
  test("Timeline: independent devices run concurrently",()=>{var p=Project.Demo();p.Devices.Add(new Device{Name="Second",Port=1503});var b=Step(0,TimelineAction.SetDrop,100,2);b.Device="Second";var r=new TimelineRunner(p,Plan(Step(0,TimelineAction.SetResponse,0,4),b));r.Advance(0);Check(!p.Devices[0].Responding&&p.Devices[1].DropPercent==100);r.Advance(2);Check(!p.Devices[0].Responding&&p.Devices[1].DropPercent==0);r.Advance(2);Check(p.Devices[0].Responding);});
  test("Timeline: overlap and duplicate writes are rejected",()=>{var p=Project.Demo();Reject(()=>Plan(Step(0,TimelineAction.RampValue,50,5),Step(2,TimelineAction.SetValue,90)).Validate(p));Reject(()=>Plan(Step(0,TimelineAction.SetDelay,10,3),Step(2,TimelineAction.RestoreDevice)).Validate(p));Reject(()=>Plan(Step(0,TimelineAction.SetValue,10),Step(0,TimelineAction.SetValue,20)).Validate(p));});
  test("Timeline: malformed timings, enums and ranges are rejected",()=>{var p=Project.Demo();foreach(var s in new[]{Step(-1,TimelineAction.SetValue),Step(10,TimelineAction.SetValue),Step(0,TimelineAction.SetValue,double.NaN),Step(0,TimelineAction.SetDelay,60001),Step(0,TimelineAction.SetDrop,101),Step(0,TimelineAction.SetException,12),Step(0,TimelineAction.SetResponse,2),Step(0,TimelineAction.RampValue,2,0),Step(0,(TimelineAction)999),Step(0,TimelineAction.SetValue,2,1),Step(9,TimelineAction.SetDrop,20,2)})Reject(()=>Plan(s).Validate(p));var t=Plan(Step(0,TimelineAction.SetValue));t.RepeatCount=0;Reject(()=>t.Validate(p));t.RepeatCount=1;t.DurationSeconds=double.PositiveInfinity;Reject(()=>t.Validate(p));});
  test("Timeline: bad references and boolean ramps rejected without mutation",()=>{var p=Project.Demo();var s=Step(0,TimelineAction.SetValue,4);s.Point="missing";Reject(()=>Plan(s).Validate(p));s.Point="Motor run";Reject(()=>Plan(s).Validate(p));s.Action=TimelineAction.RampValue;s.Value=1;s.DurationSeconds=1;Reject(()=>Plan(s).Validate(p));Near(p.Devices[0].Points[2].Value,0);});
  test("Timeline: snapshots isolate edits during a run",()=>{var p=Project.Demo();var t=Plan(Step(1,TimelineAction.SetValue,50));var r=new TimelineRunner(p,t);t.Steps[0].Value=999;r.Advance(1);Near(p.Devices[0].Points[0].Value,50);});
  test("Timeline: coarse and fine clock updates produce equivalent results across 40 schedules",()=>{for(int seed=0;seed<40;seed++){var random=new Random(seed);var t=Plan();t.RepeatCount=3;t.RestoreOnFinish=false;for(int n=0;n<9;n++){t.Steps.Add(Step(n,TimelineAction.RampValue,random.Next(1,100),0.75));t.Steps.Add(Step(n,TimelineAction.SetDelay,random.Next(1,100),0.5));}var coarse=Project.Demo();var fine=Project.Demo();var a=new TimelineRunner(coarse,t);var b=new TimelineRunner(fine,t);double target=20+random.NextDouble()*9; a.Advance(target);for(int n=0;n<200;n++)b.Advance(target/200);Near(coarse.Devices[0].Points[0].Value,fine.Devices[0].Points[0].Value);Check(coarse.Devices[0].DelayMs==fine.Devices[0].DelayMs);a.Advance(30);b.Advance(30);Near(coarse.Devices[0].Points[0].Value,fine.Devices[0].Points[0].Value);Check(a.Completed&&b.Completed);}});
  test("Timeline: empty runs and invalid elapsed time rejected",()=>{var p=Project.Demo();Reject(()=>new TimelineRunner(p,Plan()));var r=new TimelineRunner(p,Plan(Step(1,TimelineAction.SetValue,50)));foreach(double n in new[]{-1,double.NaN,double.PositiveInfinity})Reject(()=>r.Advance(n));});
  test("Timeline: native and Excel preserve all fields and actions",()=>{var p=Project.Demo();var t=Plan(Step(0,TimelineAction.SetValue,50),Step(1,TimelineAction.RampValue,70,2),Step(1,TimelineAction.SetDelay,100,2),Step(1,TimelineAction.SetResponse,0,2),Step(1,TimelineAction.SetDrop,50,2),Step(1,TimelineAction.SetException,4,2),Step(4,TimelineAction.RestoreDevice));t.Steps[0].Note="quoted, \"note\"";t.RepeatCount=3;t.RestoreOnFinish=false;p.Timelines.Add(t);foreach(string ext in new[]{"mbx","xlsx"}){string path=Path.Combine(scratch,"timeline."+ext);ProjectFiles.Save(p,path);var loaded=ProjectFiles.Load(path);var actual=loaded.Timelines.Single(x=>x.Name==t.Name);Check(actual.Steps.Count==7&&actual.RepeatCount==3&&!actual.RestoreOnFinish&&actual.Steps[0].Note==t.Steps[0].Note);var r=new TimelineRunner(loaded,actual);r.Advance(3);Near(loaded.Devices[0].Points[0].Value,70);}});
  test("Timeline: old native projects load without timelines",()=>{string path=Path.Combine(scratch,"old.mbx");Project.Demo().Save(path);var xml=XDocument.Load(path);xml.Root.Element("Timelines").Remove();xml.Save(path);Check(Project.Load(path).Timelines.Count==0);});
  test("Timeline: old Excel projects load without timeline sheets",()=>{string path=Path.Combine(scratch,"old.xlsx");ExcelProject.Export(Project.Demo(),path);using(var zip=ZipFile.Open(path,ZipArchiveMode.Update)){var entry=zip.GetEntry("xl/workbook.xml");XDocument doc;using(var stream=entry.Open())doc=XDocument.Load(stream);foreach(var el in doc.Descendants().Where(e=>e.Name.LocalName=="sheet"&&new[]{"Timelines","TimelineSteps"}.Contains((string)e.Attribute("name"))).ToList())el.Remove();entry.Delete();using(var stream=zip.CreateEntry("xl/workbook.xml").Open())doc.Save(stream);}Check(ExcelProject.Import(path).Timelines.Count==0);});
  test("Timeline: run log contains exact scheduled event times",()=>{var p=Project.Demo();var r=new TimelineRunner(p,Plan(Step(1,TimelineAction.SetDelay,100,2)));r.Advance(8);Check(r.Evidence[1].StartsWith("\"1\""));Check(r.Evidence[2].StartsWith("\"3\""));});
  test("Timeline: TCP observes scheduled values and faults",()=>Tcp());
  test("Timeline: main window playback guards and server stop recovery",()=>{
   var p=Project.Demo();p.Timelines.Clear();p.Timelines.Add(Plan(Step(0,TimelineAction.SetValue,80),Step(0,TimelineAction.SetResponse,0)));
   var socket=new TcpListener(IPAddress.Loopback,0);socket.Start();p.Devices[0].Port=((IPEndPoint)socket.LocalEndpoint).Port;socket.Stop();
   using(var form=new MainForm(p)){
    Reject(()=>Call(form,"StartTimeline"));var engine=(Engine)Field(form,"engine");engine.Start(p);Call(form,"StartTimeline");Near(p.Devices[0].Points[0].Value,80);Check(!p.Devices[0].Responding);
    Check(!((System.Windows.Forms.Button)Field(form,"timelineRun")).Enabled);Check(((System.Windows.Forms.Button)Field(form,"timelineStop")).Enabled);
    Reject(()=>Call(form,"Reset"));Reject(()=>Call(form,"EnsureTimelineIdle"));Call(form,"PauseTimeline");var runner=(TimelineRunner)Field(form,"timelineRunner");Check(runner.Paused);Call(form,"PauseTimeline");Check(!runner.Paused);
    Call(form,"Stop");Check(!engine.Running&&runner.Completed&&p.Devices[0].Responding);Near(p.Devices[0].Points[0].Value,22.5);Check(!form.Visible);
   }
  });
  test("Timeline: editor integration extends duration and rejects conflicts atomically",()=>{var p=Project.Demo();p.Timelines.Clear();p.Timelines.Add(Plan());using(var form=new MainForm(p)){var step=Step(12,TimelineAction.RampValue,50,5);Call(form,"SaveStep",null,step);Near(p.Timelines[0].DurationSeconds,17);Check(p.Timelines[0].Steps.Count==1);Reject(()=>Call(form,"SaveStep",null,Step(13,TimelineAction.SetValue,80)));Check(p.Timelines[0].Steps.Count==1);var duration=(System.Windows.Forms.NumericUpDown)Field(form,"timelineDuration");duration.Value=10;Check(!((System.Windows.Forms.Button)Field(form,"timelineRun")).Enabled);Check(((System.Windows.Forms.Label)Field(form,"timelineStatus")).Text.StartsWith("Fix timeline:"));}});
  test("Timeline: run evidence neutralizes spreadsheet formulas in device names",()=>{var p=Project.Demo();p.Timelines.Clear();p.Devices[0].Name="=1+1";var step=Step(0,TimelineAction.SetDrop,10);step.Device=p.Devices[0].Name;var r=new TimelineRunner(p,Plan(step));r.Advance(0);Check(r.Evidence[1].Contains("'="));});
  test("Timeline: new page and step editor construct without showing windows",()=>{using(var form=new MainForm()){Check(form.Controls.Find("TimelinePage",true).Length==1);Check(form.Controls.Find("TimelineSteps",true).Length==1);Check(!form.Visible);}foreach(var action in Enum.GetValues(typeof(TimelineAction)).Cast<TimelineAction>())using(var form=new StepEditor(Project.Demo(),Step(0,action,0,action==TimelineAction.RampValue?1:0))){form.PerformLayout();Check(!form.Visible&&form.Result==null);}});
 }
 static object Field(MainForm form,string name){return typeof(MainForm).GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(form);}
 static void Call(MainForm form,string name,params object[] args){typeof(MainForm).GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(form,args);}
 static void Tcp(){var p=Project.Demo();var d=p.Devices[0];var reserve=new TcpListener(IPAddress.Loopback,0);reserve.Start();d.Port=((IPEndPoint)reserve.LocalEndpoint).Port;reserve.Stop();var t=Plan(Step(1,TimelineAction.SetException,4,1),Step(3,TimelineAction.SetDelay,100,1));var value=Step(0,TimelineAction.SetValue,8);value.Point="Pressure";t.Steps.Add(value);var r=new TimelineRunner(p,t);using(var engine=new Engine()){engine.Start(p);using(var client=new TcpClient("127.0.0.1",d.Port)){client.ReceiveTimeout=2000;var stream=client.GetStream();r.Advance(0);Check(Read(stream).SequenceEqual(new byte[]{3,2,3,32}));r.Advance(1);Check(Read(stream).SequenceEqual(new byte[]{131,4}));r.Advance(1);Check(Read(stream).SequenceEqual(new byte[]{3,2,3,32}));r.Advance(1);var watch=Stopwatch.StartNew();Read(stream);Check(watch.ElapsedMilliseconds>=80);r.Stop();Check(Read(stream).SequenceEqual(new byte[]{3,2,2,108}));}engine.Stop();}}
 static byte[] Read(NetworkStream stream){byte[] req={0,1,0,0,0,6,1,3,0,2,0,1};stream.Write(req,0,req.Length);var header=Exact(stream,7);return Exact(stream,Engine.U(header,4)-1);}
 static byte[] Exact(Stream s,int count){byte[] bytes=new byte[count];int at=0;while(at<count){int n=s.Read(bytes,at,count-at);if(n==0)throw new EndOfStreamException();at+=n;}return bytes;}
}
